      a:hover {
        text-decoration: underline;
      }

      a:visited {
        color: var(--ia-theme-link-color--, #4b64ff);
      }

      #outer-container {
        padding: 3rem 1rem;
        background-color: var(--heroBlockBackgroundColor--);
        box-shadow: rgb(204, 204, 204) 1px 1px 2px 0px;
      }

      #section-container {
        display: flex;
        flex-direction: row;
      }

      .mobile #section-container {
        flex-direction: column;
      }

      #branding {
        margin: 0 1.5rem;
        flex: 1 0 20%;
        color: var(--ia-theme-link-color--);
        display: flex;
        justify-content: center;
      }
      #branding .hero-link {
        text-decoration: none;
        display: inline-block;
        color: inherit;
      }
      #branding .hero-link:hover figure {
        text-decoration: underline;
        cursor: pointer;
      }
      #branding .hero-link:focus {
        outline: 2px solid var(--ia-theme-link-color--);
        outline-offset: 4px;
      }
      #branding img {
        width: 145px;
        height: auto;
        margin-bottom: 2rem;
        margin-top: 2rem;
      }
      #branding .branding-caption {
        width: max-content;
        font-size: 1.6rem;
        font-weight: bold;
        white-space: inherit;
        margin: 0.5rem auto;
        color: var(--heroBlockFontColor--);
      }
      .branding-caption .caption-break {
        display: inline;
      }
      .mobile .branding-caption .caption-break {
        display: none;
      }

      .mobile #branding {
        margin-bottom: 2rem;
      }
      .mobile #branding img {
        margin-top: 0;
        min-height: 19rem;
      }
      .mobile .branding-caption {
        padding: 0.2em 0.2em;
      }

      #info-search {
        padding: 0 4rem;
        border-left: var(--heroBlockSeparatorStyle--);
        border-right: var(--heroBlockSeparatorStyle--);
      }

      .mobile #info-search {
        border: 0;
        padding: 0 1rem;
        margin-bottom: 2rem;
      }

      .no-announcements #info-search {
        /* Without the announcements column, this border would sit at the
           outer edge of the hero block with nothing to its right. */
        border-right: 0;
      }

      #whoweare {
        font-size: 2.6rem;
        line-height: 1.1;
        font-weight: 300;
        margin: 0 0 2rem 0;
        color: var(--heroBlockFontColor--);
      }

      #icon-block-container {
        text-align: center;
        margin-bottom: 2rem;
      }

      home-page-hero-block-icon-bar {
        min-width: 26rem;
        max-width: 44rem;
        margin: auto;
      }

      ia-dropdown-search-bar {
        --search-bar-width: 100%;
        --search-bar-height: 5rem;
        --padding-sm: 10px;
        --clear-button-width: 3rem;
        --clear-button-height: 3rem;
        --clear-button-offset: 9px;
        --dropdownFontSize: 1.4rem;
        --dropdownItemButtonPadding: 0 10px;
        font-size: 1.7rem;
      }

      #advanced-search-link {
        float: right;
        margin: 10px 0 2px;
        font-size: 1.4rem;
      }

      #announcements {
        margin: 0 4rem;
        flex: 1 0 20%;
      }

      #announcements.loading {
        min-width: 17rem;
      }

      .mobile #announcements {
        margin: 0 1rem;
      }
